// display-only: the bug TypeScript prevents
// Parent passes `name`, child expects `username`…
// Plain JS: silently renders nothing. TS: red squiggle.

// display-only
interface Props {
  name: string;
  role: string;
}

function ProfileCard({ name, role }: Props) {
  return <div><h2>{name}</h2><p>{role}</p></div>;
}

<ProfileCard name="Roli" role="dev" />      // fine
// <ProfileCard name="Roli" />               // ERROR: role missing

// display-only
interface Props {
  label: string;
  size?: string; // optional
}

function Button({ label, size = "md" }: Props) {
  return <button className={size}>{label}</button>;
}

<Button label="Save" />            // size defaults to "md"
<Button label="Save" size="lg" /> // overridden

